import static org.junit.Assert.*;

public class FitnessFunction_isFeasible_TriageGen1Test {

    /**
     * Helper method to set the private 'boundaries' field via reflection
     * since it is not exposed in the provided constructor/methods.
     */
    private void setBoundaries(CMAESOptimizer.FitnessFunction fitnessFunction, Object boundaries) throws Exception {
        Field field = CMAESOptimizer.FitnessFunction.class.getDeclaredField("boundaries");
        field.setAccessible(true);
        field.set(fitnessFunction, boundaries);
    }

    @Test
    public void testIsFeasible_BoundariesIsNull() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        // Ensure boundaries is null to trigger the first branch
        setBoundaries(fitnessFunction, null);

        double[] x = new double[]{0.5, 0.5};
        assertTrue("Should return true if boundaries is null", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_AllValuesWithinRange() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        // Mocking boundaries as non-null (using an object to trigger the loop)
        setBoundaries(fitnessFunction, new Object());

        double[] x = {0.0, 0.5, 1.0};
        assertTrue("Should return true when all values are in [0, 1]", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_ValueLessThanZero() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        setBoundaries(fitnessFunction, new Object());

        double[] x = {0.5, -0.1, 0.5};
        assertFalse("Should return false if any value is < 0", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_ValueGreaterThanOne() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        setBoundaries(fitnessFunction, new Object());

        double[] x = {0.5, 1.1, 0.5};
        assertFalse("Should return false if any value is > 1.0", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_EmptyArray() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        setBoundaries(fitnessFunction, new Object());

        double[] x = {};
        assertTrue("Should return true for an empty array if boundaries is not null", fitnessFunction.isFeasible(x));
    }

    @Test
    public void testIsFeasible_BoundaryEdgeCases() throws Exception {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer.FitnessFunction();
        setBoundaries(fitnessFunction, new Object());

        // Test exactly 0 and exactly 1
        double[] x = {0.0, 1.0};
        assertTrue("Should return true for exact boundary values 0.0 and 1.0", fitnessFunction.isFeasible(x));
    }
}
